//! HTML pages of the `posts` resource, generated by
//! `forge generate scaffold`: index, show, new/create, edit/update and
//! delete. Handlers stay thin: authorize, decode the form, call
//! [`PostService`], then render a view or redirect.
//!
//! | Method | Path | Action | Permission |
//! | --- | --- | --- | --- |
//! | `GET` | `/posts` | index | `posts:read` |
//! | `GET` | `/posts/new` | new | `posts:write` |
//! | `POST` | `/posts` | create | `posts:write` |
//! | `GET` | `/posts/{id}` | show | `posts:read` |
//! | `GET` | `/posts/{id}/edit` | edit | `posts:write` |
//! | `PATCH`, `PUT` | `/posts/{id}` | update | `posts:write` |
//! | `DELETE` | `/posts/{id}` | delete | `posts:write` |
//!
//! HTML forms send `PATCH` and `DELETE` as `POST` with `_method`; the CSRF
//! layer applies the override after checking the token. Invalid input is
//! shown again with `422`, a stale version with `409`, success redirects
//! with `303` and a flash notice.
//!
//! Live updates (`--broadcast`): after a change is stored the pages publish
//! Turbo Streams to the `posts` channel, and the
//! index page subscribes to it (see `crate::adapters::http::streams`).

use std::future::Future;
use std::sync::Arc;

use forge::ComposeError;
use forge::broadcast::Channel;
use forge::core::{ErrorCategory, ForgeError, Version};
use forge::http::{FormError, Method, Request, Response, Router, StatusCode};
use forge::security::Permission;
use forge::views::{BASE_FIELD, FieldErrors, Flash, csrf_field, csrf_token, see_other};
use forge::views::{StreamAction, TurboStreamAction, dom_id};

use crate::adapters::http::access::GlobalAccess;
use crate::adapters::http::streams::Streams;
use crate::adapters::http::views::Site;
use crate::adapters::http::views::posts::PostRowFragment;
use crate::adapters::http::views::posts::{
    PostEdit, PostFormValues, PostIndex, PostNew, PostNotFound, PostRow, PostShow,
};
use crate::application::use_cases::posts::{
    PostError, PostService, READ_PERMISSION, WRITE_PERMISSION,
};
use crate::domain::entities::post::{Post, PostAttributes, PostId, PostValidationErrors};

const STALE_UPDATE: &str = "This post was changed by someone else after you opened the form. \
     Review your changes and save again to overwrite.";
const STALE_DELETE: &str = "This post was changed by someone else. Review it and delete it again.";

/// What every post handler shares.
struct PostRoutes {
    site: Arc<Site>,
    service: PostService,
    access: Arc<dyn GlobalAccess>,
    read: Permission,
    write: Permission,
    streams: Arc<Streams>,
}

/// Registers the post routes. `access` decides who may call them (see
/// `crate::adapters::http::access`); nothing is served before it agrees.
pub fn routes(
    router: &mut Router,
    site: &Arc<Site>,
    service: PostService,
    access: Arc<dyn GlobalAccess>,
    streams: &Arc<Streams>,
) -> Result<(), ComposeError> {
    let read = Permission::new(READ_PERMISSION).map_err(ComposeError::other)?;
    // A stream of this channel is served to whoever the index may serve.
    streams.allow_global("posts", Arc::clone(&access), read.clone());
    let state = Arc::new(PostRoutes {
        site: Arc::clone(site),
        service,
        access,
        read,
        write: Permission::new(WRITE_PERMISSION).map_err(ComposeError::other)?,
        streams: Arc::clone(streams),
    });
    let collection = "/posts";
    let member = "/posts/{id}";
    route(router, &state, Method::GET, collection, index)?;
    route(
        router,
        &state,
        Method::GET,
        &format!("{collection}/new"),
        new,
    )?;
    route(router, &state, Method::POST, collection, create)?;
    route(router, &state, Method::GET, member, show)?;
    route(router, &state, Method::GET, &format!("{member}/edit"), edit)?;
    route(router, &state, Method::PATCH, member, update)?;
    route(router, &state, Method::PUT, member, update)?;
    route(router, &state, Method::DELETE, member, destroy)?;
    Ok(())
}

fn route<H, F>(
    router: &mut Router,
    state: &Arc<PostRoutes>,
    method: Method,
    path: &str,
    handler: H,
) -> Result<(), ComposeError>
where
    H: Fn(Arc<PostRoutes>, Request) -> F + Send + Sync + 'static,
    F: Future<Output = Response> + Send + 'static,
{
    let state = Arc::clone(state);
    router.route(method, path, move |request: Request| {
        handler(Arc::clone(&state), request)
    })?;
    Ok(())
}

/// Query of the index page: the cursor of the page to show.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct IndexQuery {
    after: Option<PostId>,
}

/// The submitted post form. Fields that must parse are kept as text, so
/// a value that does not parse can be shown again next to its error.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct PostForm {
    #[serde(default)]
    title: String,
    #[serde(default)]
    body: String,
    #[serde(default)]
    published: bool,
    /// The version the edit form was rendered with.
    #[serde(default)]
    version: Option<i64>,
}

/// The stored post an edit form changes, at the version it expects.
#[derive(Clone, Copy)]
struct EditTarget {
    id: PostId,
    expected: Version,
}

/// The delete form of the show page.
#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct DeleteForm {
    version: i64,
}

async fn index(state: Arc<PostRoutes>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.read).await {
        return denied.response();
    }
    let collection = collection_path();
    let Ok(query) = request.query::<IndexQuery>() else {
        return not_found(&state, &request, &collection);
    };
    match state.service.list(query.after).await {
        Ok(page) => forge::web::html(&PostIndex {
            layout: state.site.layout(&request, "Posts"),
            new_path: format!("{collection}/new"),
            rows: page
                .posts
                .iter()
                .map(|post| row(&collection, post))
                .collect(),
            next_path: page.next.map(|next| format!("{collection}?after={next}")),
            stream_source: channel().and_then(|channel| state.streams.source(&channel)),
        }),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn show(state: Arc<PostRoutes>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.read).await {
        return denied.response();
    }
    let collection = collection_path();
    let Some(id) = path_id(&request) else {
        return not_found(&state, &request, &collection);
    };
    match state.service.find(id).await {
        Ok(post) => forge::web::html(&PostShow {
            layout: state.site.layout(&request, "Post"),
            csrf_field: csrf_field_for(&request),
            back_path: collection.clone(),
            version: post.version().get(),
            post: row(&collection, &post),
        }),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn new(state: Arc<PostRoutes>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return denied.response();
    }
    let collection = collection_path();
    render_new(
        &state,
        &request,
        &collection,
        PostFormValues::default(),
        FieldErrors::new(),
        StatusCode::OK,
    )
}

async fn create(state: Arc<PostRoutes>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return denied.response();
    }
    let collection = collection_path();
    let form: PostForm = match request.form() {
        Ok(form) => form,
        Err(error) => {
            return render_new(
                &state,
                &request,
                &collection,
                PostFormValues::default(),
                decode_errors(&error),
                StatusCode::UNPROCESSABLE_ENTITY,
            );
        }
    };
    let values = form.values();
    let attributes = match form.attributes() {
        Ok(attributes) => attributes,
        Err(errors) => {
            return render_new(
                &state,
                &request,
                &collection,
                values,
                errors,
                StatusCode::UNPROCESSABLE_ENTITY,
            );
        }
    };
    match state.service.create(attributes).await {
        Ok(post) => {
            publish_created(&state, &collection, &post).await;
            redirect(
                &format!("{collection}/{}", post.id()),
                Flash::new().with_notice("Post was successfully created."),
            )
        }
        Err(PostError::Invalid(violations)) => render_new(
            &state,
            &request,
            &collection,
            values,
            field_errors(&violations),
            StatusCode::UNPROCESSABLE_ENTITY,
        ),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn edit(state: Arc<PostRoutes>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return denied.response();
    }
    let collection = collection_path();
    let Some(id) = path_id(&request) else {
        return not_found(&state, &request, &collection);
    };
    match state.service.find(id).await {
        Ok(post) => render_edit(
            &state,
            &request,
            &collection,
            &post,
            form_values(&post),
            FieldErrors::new(),
            StatusCode::OK,
        ),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn update(state: Arc<PostRoutes>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return denied.response();
    }
    let collection = collection_path();
    let Some(id) = path_id(&request) else {
        return not_found(&state, &request, &collection);
    };
    // A form that does not decode, or lacks its version, is shown again with
    // the stored values.
    let (form, expected) = match request.form::<PostForm>() {
        Ok(form) => match form.version.map(Version::new) {
            Some(Ok(expected)) => (form, expected),
            _ => {
                let mut errors = FieldErrors::new();
                errors.add(
                    BASE_FIELD,
                    "The form has no valid version; reload the page.",
                );
                return reload_edit(&state, &request, &collection, id, errors).await;
            }
        },
        Err(error) => {
            let errors = decode_errors(&error);
            return reload_edit(&state, &request, &collection, id, errors).await;
        }
    };
    let values = form.values();
    let attributes = match form.attributes() {
        Ok(attributes) => attributes,
        Err(errors) => {
            return render_form_page(
                &state,
                &request,
                &collection,
                EditTarget { id, expected },
                values,
                errors,
                StatusCode::UNPROCESSABLE_ENTITY,
            );
        }
    };
    match state.service.update(id, expected, attributes).await {
        Ok(post) => {
            publish_updated(&state, &collection, &post).await;
            redirect(
                &format!("{collection}/{}", post.id()),
                Flash::new().with_notice("Post was successfully updated."),
            )
        }
        Err(PostError::Invalid(violations)) => render_form_page(
            &state,
            &request,
            &collection,
            EditTarget { id, expected },
            values,
            field_errors(&violations),
            StatusCode::UNPROCESSABLE_ENTITY,
        ),
        Err(PostError::Conflict) => {
            // Keep the submitted values and carry the current version, so
            // saving again is a deliberate overwrite.
            match state.service.find(id).await {
                Ok(current) => {
                    let mut errors = FieldErrors::new();
                    errors.add(BASE_FIELD, STALE_UPDATE);
                    let target = EditTarget {
                        id,
                        expected: current.version(),
                    };
                    render_form_page(
                        &state,
                        &request,
                        &collection,
                        target,
                        values,
                        errors,
                        StatusCode::CONFLICT,
                    )
                }
                Err(error) => failure(&state, &request, &collection, error),
            }
        }
        Err(error) => failure(&state, &request, &collection, error),
    }
}

async fn destroy(state: Arc<PostRoutes>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return denied.response();
    }
    let collection = collection_path();
    let Some(id) = path_id(&request) else {
        return not_found(&state, &request, &collection);
    };
    let member = format!("{collection}/{id}");
    let expected = request
        .form::<DeleteForm>()
        .ok()
        .and_then(|form| Version::new(form.version).ok());
    let Some(expected) = expected else {
        let alert = "The delete form has no valid version; reload the page.";
        return redirect(&member, Flash::new().with_alert(alert));
    };
    match state.service.delete(id, expected).await {
        Ok(()) => {
            publish_deleted(&state, id).await;
            redirect(
                &collection,
                Flash::new().with_notice("Post was successfully deleted."),
            )
        }
        Err(PostError::Conflict) => redirect(&member, Flash::new().with_alert(STALE_DELETE)),
        Err(error) => failure(&state, &request, &collection, error),
    }
}

impl PostForm {
    fn values(&self) -> PostFormValues {
        PostFormValues {
            title: self.title.clone(),
            body: self.body.clone(),
            published: self.published,
        }
    }

    /// Parses the text fields. When one does not parse, the error reports it
    /// together with the business-rule violations of the other fields.
    fn attributes(&self) -> Result<PostAttributes, FieldErrors> {
        let mut errors = FieldErrors::new();
        let attributes = PostAttributes {
            title: self.title.clone(),
            body: self.body.clone(),
            published: self.published,
        };
        if errors.is_empty() {
            return Ok(attributes);
        }
        if let Err(violations) = attributes.validate() {
            for (field, violation) in violations.iter() {
                if errors.get(field.name()).is_none() {
                    errors.add(field.name(), violation.to_string());
                }
            }
        }
        Err(errors)
    }
}

/// The form values of a stored post.
fn form_values(post: &Post) -> PostFormValues {
    PostFormValues {
        title: post.title().to_owned(),
        body: post.body().to_owned(),
        published: post.published(),
    }
}

/// A post as display text.
fn row(collection: &str, post: &Post) -> PostRow {
    let show_path = format!("{collection}/{}", post.id());
    PostRow {
        dom_id: format!("post_{}", post.id()),
        edit_path: format!("{show_path}/edit"),
        show_path,
        title: post.title().to_owned(),
        body: post.body().to_owned(),
        published: yes_no(post.published()),
    }
}

fn render_new(
    state: &PostRoutes,
    request: &Request,
    collection: &str,
    form: PostFormValues,
    errors: FieldErrors,
    status: StatusCode,
) -> Response {
    forge::web::html_with_status(
        status,
        &PostNew {
            layout: state.site.layout(request, "New post"),
            csrf_field: csrf_field_for(request),
            action: collection.to_owned(),
            method: None,
            version: None,
            submit: "Create post",
            back_path: collection.to_owned(),
            form,
            errors,
        },
    )
}

fn render_edit(
    state: &PostRoutes,
    request: &Request,
    collection: &str,
    post: &Post,
    form: PostFormValues,
    errors: FieldErrors,
    status: StatusCode,
) -> Response {
    let target = EditTarget {
        id: post.id(),
        expected: post.version(),
    };
    render_form_page(state, request, collection, target, form, errors, status)
}

fn render_form_page(
    state: &PostRoutes,
    request: &Request,
    collection: &str,
    target: EditTarget,
    form: PostFormValues,
    errors: FieldErrors,
    status: StatusCode,
) -> Response {
    let show_path = format!("{collection}/{}", target.id);
    forge::web::html_with_status(
        status,
        &PostEdit {
            layout: state.site.layout(request, "Editing post"),
            csrf_field: csrf_field_for(request),
            action: show_path.clone(),
            method: Some("patch"),
            version: Some(target.expected.get()),
            submit: "Update post",
            back_path: collection.to_owned(),
            show_path,
            form,
            errors,
        },
    )
}

/// Shows the edit form again with the stored values and `errors`.
async fn reload_edit(
    state: &PostRoutes,
    request: &Request,
    collection: &str,
    id: PostId,
    errors: FieldErrors,
) -> Response {
    match state.service.find(id).await {
        Ok(post) => render_edit(
            state,
            request,
            collection,
            &post,
            form_values(&post),
            errors,
            StatusCode::UNPROCESSABLE_ENTITY,
        ),
        Err(error) => failure(state, request, collection, error),
    }
}

fn not_found(state: &PostRoutes, request: &Request, collection: &str) -> Response {
    forge::web::html_with_status(
        StatusCode::NOT_FOUND,
        &PostNotFound {
            layout: state.site.layout(request, "Post not found"),
            back_path: collection.to_owned(),
        },
    )
}

/// Maps a use-case failure that the handler does not render itself.
fn failure(state: &PostRoutes, request: &Request, collection: &str, error: PostError) -> Response {
    match error {
        PostError::NotFound => not_found(state, request, collection),
        PostError::Invalid(_) => {
            Response::new(StatusCode::UNPROCESSABLE_ENTITY, "unprocessable entity")
        }
        PostError::Conflict => Response::new(StatusCode::CONFLICT, "conflict"),
        // Logged with its cause chain; the client sees a generic report.
        PostError::Store(error) => forge::web::error(
            &ForgeError::new(
                ErrorCategory::Infrastructure,
                "post_storage_failed",
                "service temporarily unavailable",
            )
            .with_source(error),
        ),
    }
}

/// A body that does not decode was not sent by the generated form; its
/// caller-safe reason is shown above the form.
fn decode_errors(error: &FormError) -> FieldErrors {
    let mut errors = FieldErrors::new();
    errors.add(BASE_FIELD, error.kind().message());
    errors
}

fn field_errors(violations: &PostValidationErrors) -> FieldErrors {
    let mut errors = FieldErrors::new();
    for (field, violation) in violations.iter() {
        errors.add(field.name(), violation.to_string());
    }
    errors
}

/// A `303 See Other` that carries `flash` to the next page.
fn redirect(location: &str, flash: Flash) -> Response {
    let Ok(mut response) = see_other(location) else {
        return Response::empty(StatusCode::INTERNAL_SERVER_ERROR);
    };
    if flash.set_on(&mut response).is_err() {
        return Response::empty(StatusCode::INTERNAL_SERVER_ERROR);
    }
    response
}

fn csrf_field_for(request: &Request) -> String {
    csrf_token(request)
        .map(|token| csrf_field(&token))
        .unwrap_or_default()
}

/// The `{id}` of the route; a value that is not a UUIDv7 is "not found".
fn path_id(request: &Request) -> Option<PostId> {
    request.path_param_as("id").ok()
}

/// The channel the post pages publish to and subscribe to, shared by
/// everyone the access policy lets read posts.
fn channel() -> Option<Channel> {
    Channel::global("posts").ok()
}

/// Shows a new post in every open list (appended: lists are oldest
/// first) and removes the "no posts yet" row.
async fn publish_created(state: &PostRoutes, collection: &str, post: &Post) {
    let item = row(collection, post);
    state
        .streams
        .publish(channel(), || {
            Ok(vec![
                TurboStreamAction::remove(forge::views::DomId::new("posts_empty")?),
                TurboStreamAction::from_view(
                    StreamAction::Append,
                    forge::views::DomId::new("posts")?,
                    &PostRowFragment { row: item },
                )?,
            ])
        })
        .await;
}

/// Replaces the post's row in every open list.
async fn publish_updated(state: &PostRoutes, collection: &str, post: &Post) {
    let item = row(collection, post);
    let id = post.id();
    state
        .streams
        .publish(channel(), || {
            Ok(vec![TurboStreamAction::from_view(
                StreamAction::Replace,
                dom_id(id, "post")?,
                &PostRowFragment { row: item },
            )?])
        })
        .await;
}

/// Removes the post's row from every open list.
async fn publish_deleted(state: &PostRoutes, id: PostId) {
    state
        .streams
        .publish(channel(), || {
            Ok(vec![TurboStreamAction::remove(dom_id(id, "post")?)])
        })
        .await;
}

fn collection_path() -> String {
    "/posts".to_owned()
}

fn yes_no(value: bool) -> String {
    if value { "Yes" } else { "No" }.to_owned()
}
